import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });

      expect(result.results).toEqual([{ premium: 5 }]);
    });
    it("a single sword → base premium 100 G (+ 10 G first insurance + 5 G fee = 115 G)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result.results).toEqual([{ premium: 115 }]);
    });
    it.todo("a single amulet → base premium 60 G (+ 6 G first insurance + 5 G fee = 71 G)");
    it.todo("a single staff → base premium 80 G (+ 8 G first insurance + 5 G fee = 93 G)");
    it.todo("a single potion → base premium 40 G (+ 4 G first insurance + 5 G fee = 49 G)");
    it.todo("a single rune (component) → base premium 25 G");
    it.todo("a single moonstone (component) → base premium 25 G");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium (no block)");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium (no block for 7)");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword adds 50 % risk surcharge on the item base premium (100 → 150)");
    it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge (100 → 130)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30 = 180)");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("first insurance surcharge of 10 % applies to the policy base premium");
    it.todo("each contract after the first receives a 15 % follow-up discount");
    it.todo("a 5 G processing fee is added at the very end of every premium");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee");
    it.todo("policy-wide modifiers apply to the sum of all item base premiums, item modifiers only to the affected item");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed sword (steel, ench 3) → premium 165 G");
    it.todo("long-standing customer (3 years), second quote, cursed sword (steel, ench 7) → premium 160 G");
  });

  describe("quote — errors", () => {
    it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
    it.todo("deductible applies once per damaged item: sword 500 G + amulet 300 G → payout 600 G");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
    it.todo("sword (cap 2000 G), two successive claims of 1500 G: first → payout 1400 G, remaining cap 600 G");
    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remaining cap 0 G");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two sword damage entries against two insured swords → each treated as a separate damage with its own deductible");
    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — errors", () => {
    it.todo("claim references a damage whose item is not part of the policy (amulet damaged, only sword insured) → error");
    it.todo("claim references a damage entry with an unknown item type → error");
    it.todo("claim contains a damage entry with amount: -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario JSON from stdin and writes {results:[...]} to stdout in step order");
    it.todo("claim step result contains payout and remainingCap; claim refers to policy by zero-based quote step index");
    it.todo("on an invalid scenario the CLI exits with a non-zero status code and writes an error to stderr, with no results on stdout");
  });
});

