export type Item = {
  type: string;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResults = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const sumItemBasePremiums = (items: Item[]): number => {
  if (items.length === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUMS[item.type], 0);
};

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = sumItemBasePremiums(items);
  return roundInMHPCOsFavour(
    policyBasePremium +
      policyBasePremium * FIRST_INSURANCE_SURCHARGE +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return {
    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
  };
};

