  let total = 0;
  for (const [type, count] of countByType(items)) {
    total +=
      count === BLOCK_SIZE
        ? BLOCK_BASE_PREMIUM
        : count * ITEM_BASE_PREMIUMS[type];
  }
  return total;
};

