export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResults = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;

const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const basePremiumForGroup = (type: string, count: number): number =>
  count === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : count * ITEM_BASE_PREMIUMS[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + basePremiumForGroup(type, count),
    0,
  );

type SurchargeRule = {
  appliesTo: (item: Item) => boolean;
  rate: number;
};

const SURCHARGE_RULES: SurchargeRule[] = [
  {
    appliesTo: (item) => item.cursed === true,
    rate: CURSE_SURCHARGE,
  },
  {
    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
    rate: HIGH_ENCHANTMENT_SURCHARGE,
  },
];

const itemSurcharge = (item: Item): number => {
  const itemBasePremium = ITEM_BASE_PREMIUMS[item.type];
  return SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
    (surcharge, rule) => surcharge + itemBasePremium * rule.rate,
    0,
  );
};

const sumItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

const quotePremium = (items: Item[]): number => {
  const base = policyBasePremium(items);
  return roundInMHPCOsFavour(
    base +
      sumItemSurcharges(items) +
      base * FIRST_INSURANCE_SURCHARGE +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return {
    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
  };
};

