  return roundPremiumInMHPCOsFavour(
    basePremium +
      sumItemSurcharges(items) +
      sumPolicyModifiers(basePremium, context) +
      PROCESSING_FEE,
  );
};

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const reimbursementFor = (damage: Damage, insuredItems: Item[]): number => {
  const item = insuredItems.find((candidate) => candidate.type === damage.itemType);
  const isHighlyEnchanted =
    (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
  return isHighlyEnchanted
    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT
    : damage.amount;
};

const claimPayout = (damages: Damage[], insuredItems: Item[]): number =>
  damages.reduce(
    (sum, damage) => sum + reimbursementFor(damage, insuredItems) - DEDUCTIBLE,
    0,
  );

/**
 * Tracks how much cover each policy has left. A policy is identified by the
 * step index of the quote that created it, which is how claims refer to it.
 */
type PolicyLedger = {
  open: (policyId: number, items: Item[]) => void;
  insuredItems: (policyId: number) => Item[];
  /** Pays out at most the policy's remaining cap. */
  drawDown: (policyId: number, desiredPayout: number) => ClaimResult;
};

const createPolicyLedger = (): PolicyLedger => {
  const remainingCaps = new Map<number, number>();
  const insuredItems = new Map<number, Item[]>();

  return {
    open: (policyId, items) => {
      remainingCaps.set(policyId, insuranceSum(items) * CAP_MULTIPLIER);
      insuredItems.set(policyId, items);
    },

    insuredItems: (policyId) => insuredItems.get(policyId) ?? [],

    drawDown: (policyId, payout) => {
      const remainingCap = (remainingCaps.get(policyId) ?? 0) - payout;
      remainingCaps.set(policyId, remainingCap);
      return remainingCap;
    },
  };
};

