type ClaimResult = { payout: number; remainingCap: number };

const processQuote = (
  step: QuoteStep,
  policyId: number,
  scenario: Scenario,
  ledger: PolicyLedger,
): QuoteResult => {
  ledger.open(policyId, step.items);
  return {
    premium: quotePremium(step.items, {
      customer: scenario.customer,
      isFollowUpContract: policyId > 0,
    }),
  };
